> no actions need to happen on destruction
so... you like never free, never fclose, never munmap, never pthread_join, never unlock mutexes, never close network connections or what ?
Also, all of your protoypes such as
    sg_pipeline sg_alloc_pipeline() {

should really be
    sg_pipeline sg_alloc_pipeline(void) {

since the first one can actually be called with any number of arguments (in C, not in C++).
Note also that C doesn't have return-value-optimization, hence all your struct-returning functions can possibly cause a call to memcpy (won't happen when compiled in C++ mode of course) and will generally lead to much more binary bloat than the traditional C way of passing outputs as arguments.
e.g. given this trivial code in foo.c:
    typedef struct _foo
    {
        int x;
        float foo, bar;
        char z[1024]; // change this to 10024 to get a memcpy! 

    } foo;

    void do_stuff_to_foo(foo*);

    foo blah()
    {
        foo f;
        do_stuff_to_foo(&f);
        return f;
    }

A disassembly after compilation with gcc -std=c99 -O3 gives
    blah:
    .LFB0:
	pushq	%rbp
	movq	%rdi, %rbp
	pushq	%rbx
	subq	$1064, %rsp
	movq	%fs:40, %rax
	movq	%rax, 1048(%rsp)
	xorl	%eax, %eax
	movq	%rsp, %rbx
	movq	%rbx, %rdi
	call	do_stuff_to_foo@PLT
	movq	(%rsp), %rax
	leaq	8(%rbp), %rdi
	movq	%rbp, %rcx
	andq	$-8, %rdi
	movq	%rbx, %rsi
	subq	%rdi, %rcx
	movq	%rax
